    // 1. Null pointer checks (precedence)
    if ((momentum_error_nms == NULL) || (field_body_t == NULL) || 
        (command == NULL) || (achievable_torque_nm == NULL)) {
        command->command->x = 0.0;
        command->command->y = 0.0;
        command->command->z = 0.0;
        command->saturated_axes = 0U;
        achievable_torque_nm->x = 0.0;
        achievable_torque_nm->y = 0.0;
        achievable_torque_nm->z = 0.0;
        return ADCS_E_NULL;
    }

    // 2. Range/Finiteness checks
    if ((!adcs_is_finite_vec3(momentum_error_nms)) || 
        (!adcs_is_finite_vec3(field_body_t)) || 
        (!isfinite(torque_gain_s_inv)) || (!isfinite(max_dipole_a_m2)) || 
        (torque_gain_s_inv < 0.0) || (max_dipole_a_m2 < 0.0)) {
        command->command->x = 0.0;
        command->command->y = 0.0;
        command->command->z = 0.0;
        command->saturated_axes = 0U;
        achievable_torque_nm->x = 0.0;
        achievable_torque_nm->y = 0.0;
        achievable_torque_nm->z = 0.0;
        return ADCS_E_RANGE;
    }

    // 3. Degeneracy check (||B|| <= 1e-12)
    double b2 = adcs_vec3_dot(field_body_t, field_body_t);
    if (b2 <= ADCS_EPS_NORM * ADCS_EPS_NORM) {
        command->command->x = 0.0;
        command->command->y = 0.0;
        command->command->z = 0.0;
        command->saturated_axes = 0U;
        achievable_torque_nm->x = 0.0;
        achievable_torque_nm->y = 0.0;
        achievable_torque_nm->z = 0.0;
        return ADCS_E_DEGENERATE;
    }

    // 4. Compute desired torque: tau_d = -gain * h_err
    adcs_vec3_t desired_torque = adcs_vec3_scale(momentum_error_nms, -torque_gain_s_inv);

    // 5. Compute dipole moment: m = (B x tau_d) / ||B||^2
    adcs_vec3_t cross = adcs_vec3_cross(field_body_t, &desired_torque);
    adcs_vec3_t dipole = adcs_vec3_scale(&cross, 1.0 / b2);

    // 6. Norm saturation
    double norm_m = adcs_vec3_norm(&dipole);
    command->saturated_axes = 0U;
    if (norm_m > max_dipole_a_m2) {
        double scale = max_dipole_a_m2 / norm_m;
        dipole = adcs_vec3_scale(&dipole, scale);
        command->saturated_axes = 7U;
    }

    // 7. Compute achievable torque: tau = m x B
    adcs_vec3_t actual_torque = adcs_vec3_cross(&dipole, field_body_t);

    // 8. Assign outputs
    command->command = dipole;
    *achievable_torque_nm = actual_torque;

    return ADCS_OK;
}

