        cmd->command = (adcs_vec3_t){0, 0, 0};
        cmd->saturated_axes = 0U;
        *torque = (adcs_vec3_t){0, 0, 0};
        return ADCS_E_NULL;
    }

    if ((!adcs_is_finite_vec3(herr)) || (!adcs_is_finite_vec3(field)) || 
        (!isfinite(torque_gain_s_inv)) || (!isfinite(max_dipole_a_m2)) || 
        (torque_gain_s_inv < 0.0) || (max_dipole_a_m2 < 0.0)) {
        cmd->command = (adcs_vec3_t){0, 0, 0};
        cmd->saturated_axes = 0U;
        *torque = (adcs_vec3_t){0, 0, 0};
        return ADCS_E_RANGE;
    }

    b2 = adcs_vec3_dot(field, field);
    if (b2 <= 1.0e-12 * 1.0e-12) {
        cmd->command = (adcs_vec3_t){0, 0, 0};
        cmd->saturated_axes = 0U;
        *torque = (adcs_vec3_t){0, 0, 0};
        return ADCS_E_DEGENERATE;
    }

    desired = adcs_vec3_scale(herr, -torque_gain_s_inv);
    cross = adcs_vec3_cross(field, &desired);
    cmd->command = adcs_vec3_scale(&cross, 1.0 / b2);

    n = adcs_vec3_norm(&cmd->command);
    cmd->saturated_axes = 0U;
    if (n > max_dipole_a_m2) {
        scale = max_dipole_a_m2 / n;
        cmd->command = adcs_vec3_scale(&cmd->command, scale);
        cmd->saturated_axes = 7U;
    }

    *torque = adcs_vec3_cross(&cmd->command, field);

    return ADCS_OK;
}

